// P5 contract exercises of BE-L2 (p5-work-split §E.4 and §2 rule 14; T-DG5-BE-L2): getMeetingCutoffPack and
// reviewMeetingCutoffPack, each with a success and every declared refusal it can reach, through the validating
// client. The pack is generated by the real worker job (apps/worker/src/handlers/meetings.ts
// `handleMeetingCutoffScan`) for this one meeting. Every value is SYNTHETIC; a pack review is not a business approval.
import { meetingCutoffPack } from "@mth/shared/schemas";
import { expect } from "vitest";
import type { z } from "zod";
import { handleMeetingCutoffScan } from "../../../../worker/src/handlers/meetings.ts";
import { call, signIn, type P5ExerciseContext } from "../../support/harness.ts";
import { ifm } from "../../support/p2-fixtures.ts";
import { businessToday, plusDays, setupMeetingWorld } from "../governance/meeting-fixtures.ts";
import { raiseAsk } from "../governance/t16-fixtures.ts";

export const P5_MIRRORS_BE_L2: Readonly<Record<string, z.ZodType>> = {
  getMeetingCutoffPack: meetingCutoffPack,
  reviewMeetingCutoffPack: meetingCutoffPack,
};

export async function exerciseP5BeL2Operations(ctx: P5ExerciseContext): Promise<void> {
  const { api, world: w, mirrored } = ctx;
  const send = (m: string, u: string, o?: Parameters<typeof call>[3]) => call(api.app, m, u, o);
  const x = await setupMeetingWorld(api, w);
  const today = await businessToday(api);
  await raiseAsk(send, x, x.sponsor.id, plusDays(today, 15));
  // Tomorrow's Executive SteerCo: its cut-off (2 working days before) has passed, so the scan generates its pack.
  const created = await send("POST", `/api/v1/transformations/${x.transformationId}/meetings`, {
    session: x.lead.session,
    body: {
      forumId: x.forums.executive_steerco,
      scheduledDate: plusDays(today, 1),
      startTime: "09:00",
      durationMinutes: 60,
    },
  });
  expect(created.status, JSON.stringify(created.body)).toBe(201);
  const meetingId = (created.body as { id: string }).id;
  const [scan] = await handleMeetingCutoffScan(api.db, null, "contract-be-l2", { meetingIds: [meetingId] });
  expect(scan?.outcome).toBe("generated");

  const url = `/api/v1/transformations/${x.transformationId}/meetings/${meetingId}/cutoff-pack`;
  const officeB = await signIn(api.app, w.officeB.subject);
  // getMeetingCutoffPack: 200 (TL; AUD reads), 400, 401, 404 (outside scope; no pack).
  const pack = await mirrored("GET", url, { session: x.lead.session });
  expect(pack.status).toBe(200);
  expect(pack.body).toMatchObject({ status: "draft", version: 1, reviewerAssigned: true });
  expect(pack.body.agendaItemIds).toHaveLength(1);
  expect((await mirrored("GET", url, { session: x.auditor.session })).status).toBe(200);
  expect(
    (
      await mirrored("GET", `/api/v1/transformations/${x.transformationId}/meetings/not-a-uuid/cutoff-pack`, {
        session: x.lead.session,
      })
    ).status,
  ).toBe(400);
  expect((await mirrored("GET", url)).status).toBe(401);
  expect((await mirrored("GET", url, { session: officeB })).status).toBe(404);

  // reviewMeetingCutoffPack: 428, 400, 401, 403 (not the chair or secretary; AUD), 404, 409, 200, then 422.
  const review = `${url}/review`;
  const note = { note: "Synthetic: reviewed against the T16 log" };
  expect((await mirrored("POST", review, { session: x.sponsor.session, body: note })).status).toBe(428);
  expect(
    (await mirrored("POST", review, { session: x.sponsor.session, headers: ifm(1), body: { note: "x" } })).status,
  ).toBe(400);
  expect((await mirrored("POST", review, { headers: ifm(1), body: note })).status).toBe(401);
  const notReviewer = await mirrored("POST", review, { session: x.lead.session, headers: ifm(1), body: note });
  expect([notReviewer.status, notReviewer.body.code]).toEqual([403, "meeting_cutoff_pack.not_reviewer"]);
  expect((await mirrored("POST", review, { session: x.auditor.session, headers: ifm(1), body: note })).status).toBe(
    403,
  );
  expect((await mirrored("POST", review, { session: officeB, headers: ifm(1), body: note })).status).toBe(404);
  expect((await mirrored("POST", review, { session: x.sponsor.session, headers: ifm(7), body: note })).status).toBe(
    409,
  );
  const done = await mirrored("POST", review, { session: x.sponsor.session, headers: ifm(1), body: note });
  expect([done.status, done.body.status, done.body.version]).toEqual([200, "reviewed", 2]);
  const again = await mirrored("POST", review, { session: x.sponsor.session, headers: ifm(2), body: {} });
  expect([again.status, again.body.code]).toEqual([422, "meeting_cutoff_pack.already_reviewed"]);
}
